Grid.fragmentShader:
precision highp float;
uniform float _Layer1Opacity;
uniform float _Layer2Opacity;
uniform float _Layer3Opacity;
uniform float _LineWidth;
uniform float _GridSize;
uniform vec4 _GridColor1;
uniform vec4 _GridColor2;
uniform vec4 _GridColor3;
in vec2 v_uv;
out highp vec4 unity_FragColor;
vec4 unity_frag() { 



				vec2 gridUV = v_uv * _GridSize;
				vec2 grid2UV = v_uv * _GridSize * 2.0;
				vec2 grid3UV = v_uv * _GridSize * 4.0;

				vec2 lines = abs(fract(gridUV) - 0.5);
				vec2 lines2 = abs(fract(grid2UV) - 1.0);
				vec2 lines3 = abs(fract(grid3UV) - 0.0);

				vec2 aa1 = fwidth(gridUV);
				vec2 aa2 = fwidth(grid2UV);
				vec2 aa3 = fwidth(grid3UV);

				float line1x = 1.0 - smoothstep(_LineWidth, _LineWidth + aa1.x, lines.x);
				float line1y = 1.0 - smoothstep(_LineWidth, _LineWidth + aa1.y, lines.y);

				float line2x = 1.0 - smoothstep(_LineWidth * 2.0, _LineWidth * 2.0 + aa2.x, lines2.x);
				float line2y = 1.0 - smoothstep(_LineWidth * 2.0, _LineWidth * 2.0 + aa2.y, lines2.y);

				float line3x = 1.0 - smoothstep(_LineWidth * 4.0, _LineWidth * 4.0 + aa3.x, lines3.x);
				float line3y = 1.0 - smoothstep(_LineWidth * 4.0, _LineWidth * 4.0 + aa3.y, lines3.y);

				float alpha1 = max(line1x, line1y) * _Layer1Opacity;
				float alpha2 = max(line2x, line2y) * _Layer2Opacity;
				float alpha3 = max(line3x, line3y) * _Layer3Opacity;

				vec4 col1 = _GridColor1 * alpha1;
				vec4 col2 = _GridColor2 * alpha2;
				vec4 col3 = _GridColor3 * alpha3;

				vec4 final_color = col1 + col2 + col3;

				final_color.a = clamp(final_color.a, 0.0, 1.0);
				return final_color;
			}
void main() {
    vec4 c = unity_frag();
#ifdef UNITY_LINEAR
    c = linearToOutputTexel(c);
#endif
    unity_FragColor = c;
}

Data.vertexShader:
uniform mat4 _ObjectToWorld;
in mat4 a_Transforms;
in vec4 a_Colors;
out vec4 v_color;
vec4 unityObjectToClipPos(vec4 p) { return projectionMatrix * modelViewMatrix * p; }
vec4 unityObjectToClipPos(vec3 p) { return projectionMatrix * modelViewMatrix * vec4(p, 1.0); }
void main() {
					mat4 modelMatrix = a_Transforms;
					vec4 instanceColor = a_Colors;

					vec4 wpos = (modelMatrix * vec4(position, 1.0));
					gl_Position = ((projectionMatrix * viewMatrix) * wpos);
					v_color = instanceColor;
}

